INSERT INTO TarotCards (id, title, arcana, image, description, sortOrder, lastUpdated) VALUES
  ('fool', 'The Fool', 'Major Arcana', 'cards/fool.jpg', 'A leap of faith into the unknown. The Fool stands at the edge of a cliff with only a small bag and a dog at his heels, ready to begin a journey full of possibility and innocent trust.', 0, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('magician', 'The Magician', 'Major Arcana', 'cards/magician.jpg', 'Manifestation and resourcefulness. With one hand raised to heaven and one pointing to earth, the Magician shows you already hold every tool needed to turn an idea into reality.', 1, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('high-priestess', 'The High Priestess', 'Major Arcana', 'cards/high-priestess.jpg', 'Intuition, mystery, and inner knowledge. Seated between the black and white pillars, she guards the secrets that surface when you trust your instincts over what is obvious.', 2, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('empress', 'The Empress', 'Major Arcana', 'cards/empress.jpg', 'Abundance, fertility, and nurturing creativity. Surrounded by a lush garden and a field of wheat, she is the energy of growth, comfort, and natural plenty.', 3, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('emperor', 'The Emperor', 'Major Arcana', 'cards/emperor.jpg', 'Structure, authority, and discipline. Seated on his stone throne, he provides stability and order — the framework that turns chaos into something lasting.', 4, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('hierophant', 'The Hierophant', 'Major Arcana', 'cards/hierophant.jpg', 'Tradition, spiritual guidance, and shared wisdom. He is the bridge between the sacred and the everyday, offering teachings passed down through generations.', 5, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('lovers', 'The Lovers', 'Major Arcana', 'cards/lovers.jpg', 'Love, harmony, and a meaningful choice. More than romance, this card speaks of alignment — a decision made with the whole heart.', 6, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('chariot', 'The Chariot', 'Major Arcana', 'cards/chariot.jpg', 'Determination, willpower, and victory through focus. Two sphinxes pull in different directions, yet the charioteer keeps them both moving forward.', 7, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('strength', 'Strength', 'Major Arcana', 'cards/strength.jpg', 'Courage, patience, and gentle mastery over instinct. The woman calmly closes the lion''s jaws, showing that true power comes from compassion, not force.', 8, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('hermit', 'The Hermit', 'Major Arcana', 'cards/hermit.jpg', 'Solitude, introspection, and inner guidance. With his lantern raised high, he lights the way for anyone willing to look within for answers.', 9, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wheel-of-fortune', 'Wheel of Fortune', 'Major Arcana', 'cards/wheel-of-fortune.jpg', 'Cycles, fate, and turning points. The wheel never stops spinning — what rises must fall — bringing change beyond your control but not beyond your understanding.', 10, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('justice', 'Justice', 'Major Arcana', 'cards/justice.jpg', 'Fairness, truth, and consequence. With her scales and her sword, she reminds you that every choice carries a weight and every action has an answer.', 11, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('hanged-man', 'The Hanged Man', 'Major Arcana', 'cards/hanged-man.jpg', 'Surrender, new perspective, and letting go. Suspended upside down, he sees the world differently — sometimes you must pause in order to gain clarity.', 12, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('death', 'Death', 'Major Arcana', 'cards/death.jpg', 'Transformation, endings, and rebirth. Not a literal death, but the necessary ending that clears the ground for something new to begin.', 13, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('temperance', 'Temperance', 'Major Arcana', 'cards/temperance.jpg', 'Balance, moderation, and patient blending. The angel pours water between two cups, showing that harmony comes from mixing opposites in the right measure.', 14, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('devil', 'The Devil', 'Major Arcana', 'cards/devil.jpg', 'Bondage, materialism, and the shadow self. Chained to the pedestal, the figures could leave at any moment — the card asks what truly holds you back.', 15, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('tower', 'The Tower', 'Major Arcana', 'cards/tower.jpg', 'Sudden upheaval and revelation. Struck by lightning, the tower crumbles — false structures fall away and truth remains in the ashes.', 16, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('star', 'The Star', 'Major Arcana', 'cards/star.jpg', 'Hope, inspiration, and healing. Kneeling by the water, the figure pours life back into the world — a gentle promise that renewal follows hardship.', 17, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('moon', 'The Moon', 'Major Arcana', 'cards/moon.jpg', 'Illusion, fear, and the subconscious. The moon lights the path but distorts it — not everything in the dark is what it seems; trust your intuition.', 18, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('sun', 'The Sun', 'Major Arcana', 'cards/sun.jpg', 'Joy, success, and vitality. The sun shines over a walled garden where a child rides a white horse — pure, uncomplicated happiness.', 19, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('judgement', 'Judgement', 'Major Arcana', 'cards/judgement.jpg', 'Rebirth, inner calling, and absolution. The angel''s trumpet wakes the figures from their graves — a call to rise, answer, and begin again.', 20, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('world', 'The World', 'Major Arcana', 'cards/world.jpg', 'Completion, integration, and wholeness. Dancing inside a laurel wreath, the figure has finished the great journey — achievement and the close of a cycle.', 21, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-ace', 'Ace of Wands', 'Wands', 'cards/wands-ace.jpg', 'A spark of inspiration and raw creative potential. A hand emerges from the clouds holding a sprouting wand — the seed of a bold new venture.', 22, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-02', 'Two of Wands', 'Wands', 'cards/wands-02.jpg', 'Planning, decision, and looking toward the horizon. Standing on a castle battlement with a globe in hand, you weigh the world — the choice of where to go next is yours.', 23, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-03', 'Three of Wands', 'Wands', 'cards/wands-03.jpg', 'Expansion, foresight, and early success. Ships sail on the horizon while the merchant watches from the shore — your groundwork is beginning to pay off.', 24, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-04', 'Four of Wands', 'Wands', 'cards/wands-04.jpg', 'Celebration, harmony, and a milestone reached. A garlanded pavilion marks a happy occasion — homecoming, reunion, or a well-earned rest.', 25, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-05', 'Five of Wands', 'Wands', 'cards/wands-05.jpg', 'Conflict, competition, and clashing egos. Five figures swing their wands in a mock battle — disagreement tests you, but it need not defeat you.', 26, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-06', 'Six of Wands', 'Wands', 'cards/wands-06.jpg', 'Victory, recognition, and public success. Carried on shoulders through cheering crowds, the rider shows that effort is seen and rewarded.', 27, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-07', 'Seven of Wands', 'Wands', 'cards/wands-07.jpg', 'Defense, perseverance, and protecting your ground. From the hilltop you fend off attackers from above — you hold the advantage, so stand firm.', 28, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-08', 'Eight of Wands', 'Wands', 'cards/wands-08.jpg', 'Speed, swift action, and rapid movement. Eight wands fly through the air like arrows — a message, project, or change arriving faster than expected.', 29, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-09', 'Nine of Wands', 'Wands', 'cards/wands-09.jpg', 'Resilience, grit, and the last stand. Wounded but watchful, you lean on your wand — tired, perhaps, but nearly there. Keep going.', 30, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-10', 'Ten of Wands', 'Wands', 'cards/wands-10.jpg', 'Burden, responsibility, and overwhelm. Carrying all ten wands at once, you struggle forward — success can become a weight when you carry it alone.', 31, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-page', 'Page of Wands', 'Wands', 'cards/wands-page.jpg', 'Curiosity, exploration, and a burst of creative energy. The page gazes at his wand like a messenger bearing exciting news — a new passion to pursue.', 32, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-knight', 'Knight of Wands', 'Wands', 'cards/wands-knight.jpg', 'Impulsiveness, adventure, and charging ahead. The knight rides off in search of quests — bold, passionate action, sometimes without a plan.', 33, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-queen', 'Queen of Wands', 'Wands', 'cards/wands-queen.jpg', 'Confidence, warmth, and independent determination. Seated with her wand, she is fire made steady — a charismatic presence who inspires everyone around her.', 34, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('wands-king', 'King of Wands', 'Wands', 'cards/wands-king.jpg', 'Vision, leadership, and mastery of fire. The king holds his wand like a scepter — bold ideas executed with the authority of hard-won experience.', 35, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-ace', 'Ace of Cups', 'Cups', 'cards/cups-ace.jpg', 'An overflowing cup of new love, joy, and emotional beginnings. A hand from the clouds offers a vessel brimming with feeling — a fresh start of the heart.', 36, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-02', 'Two of Cups', 'Cups', 'cards/cups-02.jpg', 'Partnership, mutual attraction, and union. Two figures exchange cups face to face — a meaningful connection built on equality and affection.', 37, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-03', 'Three of Cups', 'Cups', 'cards/cups-03.jpg', 'Friendship, community, and shared celebration. Three women raise their cups in a joyful gathering — togetherness and collective happiness.', 38, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-04', 'Four of Cups', 'Cups', 'cards/cups-04.jpg', 'Apathy, contemplation, and a missed opportunity. Seated under a tree, the figure ignores the cup offered from a cloud — sometimes you must look up to see what is being given.', 39, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-05', 'Five of Cups', 'Cups', 'cards/cups-05.jpg', 'Loss, grief, and dwelling on what is gone. Kneeling before three spilled cups, the figure mourns — but two cups still stand behind him. Not all is lost.', 40, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-06', 'Six of Cups', 'Cups', 'cards/cups-06.jpg', 'Nostalgia, childhood memory, and innocent joy. Children fill their cups in a garden — a return to simpler times and pure, uncomplicated happiness.', 41, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-07', 'Seven of Cups', 'Cups', 'cards/cups-07.jpg', 'Choices, fantasy, and wishful thinking. Seven cups drift in the clouds, each holding a vision — dreams are abundant, but only one can become real.', 42, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-08', 'Eight of Cups', 'Cups', 'cards/cups-08.jpg', 'Walking away, deeper meaning, and leaving the familiar. The figure departs at night with six cups behind — sometimes growth means leaving what is comfortable.', 43, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-09', 'Nine of Cups', 'Cups', 'cards/cups-09.jpg', 'Contentment, satisfaction, and a wish fulfilled. Arms crossed before nine full cups, the figure savours the quiet joy of having enough.', 44, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-10', 'Ten of Cups', 'Cups', 'cards/cups-10.jpg', 'Lasting harmony, love, and emotional fulfillment. A rainbow arcs over a family dancing together — deep belonging and a happy home.', 45, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-page', 'Page of Cups', 'Cups', 'cards/cups-page.jpg', 'Creativity, intuition, and a gentle new message. The page gazes at the fish in his cup — a sensitive soul receiving emotional or artistic inspiration.', 46, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-knight', 'Knight of Cups', 'Cups', 'cards/cups-knight.jpg', 'Romance, charm, and following the heart. The knight rides a white horse bearing a cup — an offer of love, or a creative pursuit chased with idealism.', 47, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-queen', 'Queen of Cups', 'Cups', 'cards/cups-queen.jpg', 'Compassion, emotional maturity, and deep intuition. Seated by the sea with her cup, she is a nurturing, empathic presence who feels more than she says.', 48, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('cups-king', 'King of Cups', 'Cups', 'cards/cups-king.jpg', 'Emotional balance, diplomacy, and mastery of feelings. Ruling the waves from his throne, he is calm control over deep waters — generous, wise, and kind.', 49, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-ace', 'Ace of Swords', 'Swords', 'cards/swords-ace.jpg', 'A breakthrough of clarity and a piercing new idea. The hand from the clouds raises a sword crowned with laurels — the triumph of the mind.', 50, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-02', 'Two of Swords', 'Swords', 'cards/swords-02.jpg', 'Indecision, difficult choices, and stalemate. Blindfolded and balancing two crossed blades, the figure shows that the hardest choice is often the one you avoid.', 51, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-03', 'Three of Swords', 'Swords', 'cards/swords-03.jpg', 'Heartbreak, sorrow, and painful truth. A storm rages over a heart pierced by three swords — grief that is real, but not forever.', 52, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-04', 'Four of Swords', 'Swords', 'cards/swords-04.jpg', 'Rest, recovery, and quiet contemplation. The figure lies in peaceful repose — a necessary pause that restores your strength.', 53, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-05', 'Five of Swords', 'Swords', 'cards/swords-05.jpg', 'Conflict, hollow victory, and winning at a cost. The victor gathers swords while others retreat — a win that can leave you poorer than before.', 54, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-06', 'Six of Swords', 'Swords', 'cards/swords-06.jpg', 'Transition, moving on, and leaving turmoil behind. A ferryman carries passengers toward calm waters — a journey toward healing and a gentler shore.', 55, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-07', 'Seven of Swords', 'Swords', 'cards/swords-07.jpg', 'Strategy, deception, and slipping away. The figure creeps off with five swords, leaving two behind — sometimes you must act quietly to get what you need.', 56, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-08', 'Eight of Swords', 'Swords', 'cards/swords-08.jpg', 'Restriction, negative thoughts, and feeling trapped. Bound and blindfolded before eight swords, the figure reminds you that the cage is often one you build yourself.', 57, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-09', 'Nine of Swords', 'Swords', 'cards/swords-09.jpg', 'Anxiety, worry, and sleepless nights. Sitting up in bed with nine swords on the wall, the figure shows how fear looms largest in the dark.', 58, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-10', 'Ten of Swords', 'Swords', 'cards/swords-10.jpg', 'Painful endings, deep wounds, and rock bottom. Pierced by ten swords at dawn — the darkest moment right before the light returns.', 59, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-page', 'Page of Swords', 'Swords', 'cards/swords-page.jpg', 'Vigilance, curiosity, and a sharp new idea. The page raises his sword — an eager mind hunting for truth and fresh perspectives.', 60, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-knight', 'Knight of Swords', 'Swords', 'cards/swords-knight.jpg', 'Ambition, action, and charging into battle. The knight gallops with his sword raised — swift and decisive, and sometimes reckless.', 61, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-queen', 'Queen of Swords', 'Swords', 'cards/swords-queen.jpg', 'Independence, clear boundaries, and honest intellect. Seated among the clouds with her sword, she is uncompromising truth — perceptive, fair, and direct.', 62, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('swords-king', 'King of Swords', 'Swords', 'cards/swords-king.jpg', 'Authority, truth, and intellectual power. The king lifts his sword to the sky — reason and justice wielded with a steady, incorruptible hand.', 63, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-ace', 'Ace of Pentacles', 'Pentacles', 'cards/pentacles-ace.jpg', 'A new financial opportunity and a material beginning. The hand from the cloud offers a golden pentacle — prosperity and security taking root.', 64, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-02', 'Two of Pentacles', 'Pentacles', 'cards/pentacles-02.jpg', 'Balance, adaptability, and juggling priorities. The figure dances with two pentacles linked by an infinity ribbon — keeping many things in motion at once.', 65, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-03', 'Three of Pentacles', 'Pentacles', 'cards/pentacles-03.jpg', 'Teamwork, craftsmanship, and collaboration. The mason carves a cathedral arch while his client looks on — skill recognized and rewarded through cooperation.', 66, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-04', 'Four of Pentacles', 'Pentacles', 'cards/pentacles-04.jpg', 'Security, control, and holding on tightly. Pentacles clutched to crown, hands, and feet give stability — but at the cost of openness.', 67, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-05', 'Five of Pentacles', 'Pentacles', 'cards/pentacles-05.jpg', 'Hardship, loss, and feeling left out in the cold. Two figures pass a lit window in the snow — struggle is real, but shelter and help exist if you ask for them.', 68, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-06', 'Six of Pentacles', 'Pentacles', 'cards/pentacles-06.jpg', 'Generosity, giving, and fair exchange. The merchant weighs coins on his scales, giving to those in need — charity and balanced reciprocity.', 69, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-07', 'Seven of Pentacles', 'Pentacles', 'cards/pentacles-07.jpg', 'Patience, long-term view, and assessing progress. The farmer leans on his staff, surveying vines heavy with fruit — hard work is growing, but the harvest is not yet in.', 70, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-08', 'Eight of Pentacles', 'Pentacles', 'cards/pentacles-08.jpg', 'Apprenticeship, skill, and diligent practice. The artisan carves pentacles one by one — mastery comes from focused, repeated effort.', 71, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-09', 'Nine of Pentacles', 'Pentacles', 'cards/pentacles-09.jpg', 'Luxury, self-sufficiency, and enjoying the fruits of labor. The woman walks her vineyard with a hooded falcon — independence and refined comfort.', 72, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-10', 'Ten of Pentacles', 'Pentacles', 'cards/pentacles-10.jpg', 'Wealth, inheritance, and lasting legacy. A family beneath an archway of pentacles — prosperity shared across generations.', 73, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-page', 'Page of Pentacles', 'Pentacles', 'cards/pentacles-page.jpg', 'Ambition, practicality, and a new opportunity. The page studies his pentacle — a grounded approach to manifesting material goals.', 74, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-knight', 'Knight of Pentacles', 'Pentacles', 'cards/pentacles-knight.jpg', 'Hard work, routine, and dependable progress. The knight rides slowly across fertile fields — steady, methodical effort that reliably gets results.', 75, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-queen', 'Queen of Pentacles', 'Pentacles', 'cards/pentacles-queen.jpg', 'Nurturing, practicality, and abundant comfort. Seated in her lush garden, she is a generous provider of material and emotional security.', 76, strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  ('pentacles-king', 'King of Pentacles', 'Pentacles', 'cards/pentacles-king.jpg', 'Success, abundance, and material mastery. The king on his throne, the bull''s head on his pedestal — wealth and business acumen at their peak.', 77, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
